it('P1: chuyên viên (trần ≤500tr) duyệt hồ sơ 600tr do người khác tạo phải bị chặn (authority bypass)', async () => {
    const dx = await taoDeXuat('HM-2026-8001', 600_000_000, 'hung');

    const res = await app.inject({
      method: 'POST',
      url: `/api/de-xuat/${dx.id}/duyet`,
      headers: { 'x-user': 'lan' },
    });

    expect(res.statusCode).toBe(403);
    expect(JSON.stringify(res.json())).toContain('500.000.000');

    const ds = await layDanhSach();
    const found = ds.find((d) => d.so_ho_so === 'HM-2026-8001');
    expect(found?.trang_thai).toBe('cho_duyet');
  });

