    expect(JSON.stringify(res.json())).toContain('Người tạo đề xuất không được tự phê duyệt');

    const ds = await layDanhSach();
    const found = ds.find((d) => d.so_ho_so === 'HM-2026-8002');
    expect(found?.trang_thai).toBe('cho_duyet');
  });

